"""Money helpers.

Historically everything in this package used raw floats. A Decimal-based
``Money`` value type is being introduced; most modules have not migrated yet.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP

TWO_PLACES = Decimal("0.01")


def quantize(amount: Decimal) -> Decimal:
    """Round a Decimal to two places using ROUND_HALF_UP."""
    if not isinstance(amount, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return amount.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    @classmethod
    def of(cls, amount: Decimal, currency: str = "USD") -> "Money":
        """Build a Money value, quantizing the amount to two places first."""
        return cls(quantize(amount), currency)

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money.of(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money.of(self.amount - other.amount, self.currency)

    def __mul__(self, multiplier: Decimal | int) -> "Money":
        if isinstance(multiplier, bool):
            raise TypeError("Money cannot be multiplied by a bool")
        if isinstance(multiplier, int):
            multiplier = Decimal(multiplier)
        if not isinstance(multiplier, Decimal):
            raise TypeError("Money can only be multiplied by an int or Decimal")
        return Money.of(self.amount * multiplier, self.currency)

    __rmul__ = __mul__

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"

