"""Discount rules, now Decimal/Money aware."""

from __future__ import annotations

from decimal import Decimal

from .money import Money, quantize


def percentage_off(amount: Money, percent: Decimal) -> Money:
    factor = Decimal("1") - (Decimal(percent) / Decimal("100"))
    return Money.of(amount.amount * factor, amount.currency)


def flat_off(amount: Money, discount: Money) -> Money:
    result = amount.amount - discount.amount
    if result < 0:
        result = Decimal("0.00")
    return Money.of(result, amount.currency)


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity.

    Not part of the money path (it feeds a percentage into
    ``percentage_off``, it never touches an amount itself) so it keeps its
    original float-returning signature for backwards compatibility.
    """
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

