from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog, discounts
from .money import Money
from .tax import TAX_RATE

__all__ = ["InvoiceLine", "Invoice", "TAX_RATE"]


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        gross = catalog.unit_price(line.sku) * line.quantity
        return discounts.percentage_off(gross, line.discount_percent)

    def subtotal(self) -> Money:
        total = Money(Decimal("0.00"))
        for line in self.lines:
            total = total + self.line_amount(line)
        return total

    def tax(self) -> Money:
        taxable = Money(Decimal("0.00"))
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable = taxable + self.line_amount(line)
        return Money.of(taxable.amount * TAX_RATE)

    def total(self) -> Money:
        return self.subtotal() + self.tax()

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            rows.append(f"{product.name} x{line.quantity}  {self.line_amount(line).amount:.2f}")
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

